positional:
var g = SugarCube.State.variables;
g.flags = g.flags || {};
g.flags.sal_opened_up = true;
g.flags.sal_after_hours_done = false;
g.player.core_traits.corruption = 25;
var S = SugarCube.setup;
var card = S.pickQuestsCard('npc_sal');
var goals = card ? S.evaluateGoals(card) : null;
var found = (card && card.ready_canvas) ? S.lookupCanvasBySlug(card.ready_canvas) : null;
var loc = found ? S._locNameFromUuid(found.locUuid) : null;
var sched = found ? S._formatCanvasSchedule(found.canvas) : null;
return JSON.stringify({ready_canvas: card?card.ready_canvas:'(no card)', allMet: goals?goals.allMet:null, next_loc: loc, next_sched: sched});
